[?2004l<!doctype html>
<html lang="en">
  <head>
    <meta charset="utf-8" />
    <meta name="viewport" content="width=device-width, initial-scale=1" />
    <title>Northstar Home Goods</title>
    <style>
      :root {
        color-scheme: light;
        font-family: Inter, Arial, sans-serif;
        background: #f6f3ef;
        color: #222;
      }
      body {
        margin: 0;
      }
      header {
        background: #12343b;
        color: #fff;
        padding: 28px 48px;
      }
      header h1 {
        margin: 0 0 8px;
        font-size: 34px;
      }
      header p {
        margin: 0;
        max-width: 760px;
        color: #d8e7e9;
      }
      main {
        max-width: 1180px;
        margin: 0 auto;
        padding: 28px 32px 56px;
      }
      .toolbar {
        display: flex;
        gap: 12px;
        align-items: center;
        margin-bottom: 20px;
      }
      .toolbar input,
      .toolbar select {
        border: 1px solid #c7c0b8;
        border-radius: 6px;
        padding: 10px 12px;
        font-size: 15px;
        background: #fff;
      }
      .toolbar input {
        flex: 1;
      }
      .grid {
        display: grid;
        grid-template-columns: repeat(auto-fit, minmax(240px, 1fr));
        gap: 18px;
      }
      article {
        border: 1px solid #d6cec5;
        border-radius: 8px;
        background: #fff;
        overflow: hidden;
        min-height: 390px;
        display: flex;
        flex-direction: column;
      }
      .product-media {
        display: block;
        width: 100%;
        aspect-ratio: 3 / 2;
        object-fit: cover;
        background: #ece5dc;
        border-bottom: 1px solid #d6cec5;
      }
      .product-body {
        padding: 18px;
        display: flex;
        flex: 1;
        flex-direction: column;
      }
      .product-id {
        color: #66706b;
        font-size: 13px;
      }
      h2 {
        margin: 8px 0;
        font-size: 22px;
      }
      .price {
        font-size: 24px;
        font-weight: 700;
        color: #1d5f53;
      }
      .rating {
        color: #6b4f00;
        margin: 8px 0;
      }
      .summary {
        line-height: 1.45;
      }
